#pragma once
#include "../../support.hpp"
namespace algs {
struct AhoMatch{std::string pattern;int index;};class AhoCorasick{struct Node{std::map<char,int>next;int fail=0;std::vector<int>output;};std::vector<Node>nodes{Node{}};std::vector<std::string>patterns;int transition(int state,char c)const{while(true){auto it=nodes[state].next.find(c);if(it!=nodes[state].next.end())return it->second;if(!state)return 0;state=nodes[state].fail;}}public:explicit AhoCorasick(std::vector<std::string>p):patterns(std::move(p)){for(int index=0;index<int(patterns.size());++index){if(patterns[index].empty())continue;int state=0;for(char c:patterns[index]){auto it=nodes[state].next.find(c);if(it==nodes[state].next.end()){int next=int(nodes.size());nodes.push_back(Node{});nodes[state].next[c]=next;state=next;}else state=it->second;}nodes[state].output.push_back(index);}std::vector<int>q;for(auto [c,child]:nodes[0].next)q.push_back(child);for(int head=0;head<int(q.size());++head){int state=q[head];for(auto [c,child]:nodes[state].next){int fail=transition(nodes[state].fail,c);nodes[child].fail=fail;nodes[child].output.insert(nodes[child].output.end(),nodes[fail].output.begin(),nodes[fail].output.end());q.push_back(child);}}}std::vector<AhoMatch>search(const std::string&t)const{std::vector<AhoMatch>matches;int state=0;for(int i=0;i<int(t.size());++i){state=transition(state,t[i]);for(int p:nodes[state].output)matches.push_back({patterns[p],i-int(patterns[p].size())+1});}return matches;}};
}
